// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;

    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address actor, uint96 amount, address lfAddr) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);

        // minimal functioning log deployed by the test; its address is fuzzed-influenced
        address lf = address(new LogHelper());
        vm.assume(lfAddr != lf);

        c.SetLogFile(lf);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }

        // After SetLogFile(lf) with a valid log, any deposit must succeed and be credited.
        assertTrue(ok && c.balances(actor) == amount, "Deposit must succeed and credit after SetLogFile");
    }
}

contract LogHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string calldata _data) external {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
